SELECT A.SURVEY_SEQ, A.SURVEY_ID, A.SURVEY_TITLE, A.OPENED, A.CLOSED, A.ADMINEMAIL, A.BGCOLOR, A.TEXTCOLOR, A.REGISTER_NO, DATE_FORMAT(A.REGIST_DT, '%Y-%m-%d %H:%i') AS REGIST_DT, A.UPDUSR_NO, DATE_FORMAT(A.UPDT_DT, '%Y-%m-%d %H:%i') AS UPDT_DT FROM tb_survey A WHERE 1=1
AND ( A.SURVEY_TITLE LIKE CONCAT('%', #{searchKeyword}, '%') OR A.SURVEY_ID LIKE CONCAT('%', #{searchKeyword}, '%') )
ORDER BY A.REGIST_DT DESC LIMIT #{firstIndex}, #{recordCountPerPage}

SELECT
    *
FROM tb_survey
WHERE 1=1

    AND SURVEY_SEQ = #{surveySeq}


    AND SURVEY_ID = #{surveyId}

SELECT * FROM tb_section
WHERE SURVEY_ID = #{surveyId}
ORDER BY SECTION_ID ASC

SELECT * FROM tb_question
WHERE SURVEY_ID = #{surveyId}
ORDER BY SECTION_ID, QUESTION_ID ASC

SELECT * FROM tb_question_label
WHERE SURVEY_ID = #{surveyId}
ORDER BY SECTION_ID, QUESTION_ID, QUESTION_LABEL_ID ASC
